&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Contributing to certain areas of practice development (e.g., mentoring, training)&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Qualifications:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Minimum Required:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bachelor’s degree, with a record of academic excellence&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;3-5 years of consulting or related business analytics/strategy experience within the healthcare space (pharmaceutical, biotech, medical device, diagnostics industry) &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Knowledge of global pricing &amp;amp; market access, developed via experience in healthcare consulting or within the pharmaceutical industry &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Strong MS Office literacy e.g., Word, PowerPoint, Excel&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Preferred:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Academic concentration in Science, Economics, Business&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Master’s degree or PhD&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;Precision is required by law in some states or cities to include a reasonable estimate of the compensation range for this role. This compensation range takes into account the wide range of factors that are considered in making compensation decisions including but not limited to: skill sets, experience and training, licensure and certifications, and other business and organizational needs. The disclosed range estimate has not been adjusted for the applicable geographic differential associated with the location at which the position may be filled. At Precision, it is not typical for an individual to be hired at or near the top of the range for their role and compensation decisions are dependent on the facts and circumstances of each case.&amp;nbsp; This role is also eligible for a discretionary annual bonus, health insurance, retirement savings benefits, life insurance and disability benefits, parental leave, and paid time off for sick leave and vacation, among other benefits.&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Reasonable estimate of the current range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$105,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$182,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Any data provided as a part of this application will be stored in accordance with our &lt;a href=&quot;https://nam12.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.precisionmedicinegrp.com%2Fprivacy-policy%2F&amp;amp;data=05%7C01%7Czeta.larcon%40precisionmedicinegrp.com%7Cb58fe8b0c3ea4dd2e79d08db5bd09a25%7Cb71ff3f628164ca8a9b938f820f91ad1%7C0%7C0%7C638204723732367131%7CUnknown%7CTWFpbGZsb3d8eyJWIjoiMC4wLjAwMDAiLCJQIjoiV2luMzIiLCJBTiI6Ik1haWwiLCJXVCI6Mn0%3D%7C3000%7C%7C%7C&amp;amp;sdata=9DgboiHTFPrNYVhdKhyfdwVyNYwUvZbP%2FroLdWIIfxw%3D&amp;amp;reserved=0&quot;&gt;Privacy Policy.&lt;/a&gt;&amp;nbsp;For CA applicants, please also refer to our&amp;nbsp;&lt;a href=&quot;https://nam12.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.precisionmedicinegrp.com%2Fca-applicants-privacy-notice%2F&amp;amp;data=05%7C01%7Czeta.larcon%40precisionmedicinegrp.com%7Cb58fe8b0c3ea4dd2e79d08db5bd09a25%7Cb71ff3f628164ca8a9b938f820f91ad1%7C0%7C0%7C638204723732367131%7CUnknown%7CTWFpbGZsb3d8eyJWIjoiMC4wLjAwMDAiLCJQIjoiV2luMzIiLCJBTiI6Ik1haWwiLCJXVCI6Mn0%3D%7C3000%7C%7C%7C&amp;amp;sdata=tfAqqMZsG%2B11IchL45HFFVbfECCkYqQpNr0PQxrMFJU%3D&amp;amp;reserved=0&quot;&gt;CA Privacy Notice&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;Precision Medicine Group is an Equal Opportunity Employer. Employment decisions are made without regard to race, color, age, religion, sex, sexual orientation, gender identity, national origin, disability, veteran status or other characteristics protected by law.&lt;/p&gt;
&lt;p&gt;If you are an individual with a disability and require a reasonable accommodation to complete any part of the application process or are limited in the ability or unable to access or use this online application process and need an alternative method for applying, you may contact Precision Medicine Group at&amp;nbsp;&lt;a href=&quot;mailto:QuestionForHR@precisionmedicinegrp.com&quot;&gt;QuestionForHR@precisionmedicinegrp.com&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;It has come to our attention that some individuals or organizations are reaching out to job seekers and posing as potential employers presenting enticing employment offers. We want to emphasize that these offers are not associated with our company and may be fraudulent in nature. Please note that our organization will not extend a job offer without prior communication with our recruiting team, hiring managers and a formal interview process.&lt;/p&gt;&lt;/div&gt;

mbaexchange-roblox:greenhouse:7711780.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Every day, tens of millions of people come to Roblox to explore, create, play, learn, and connect with friends in 3D immersive digital experiences– all created by our global community of developers and creators.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At Roblox, we’re building the tools and platform that empower our community to bring any experience that they can imagine to life. Our vision is to reimagine the way people come together, from anywhere in the world, and on any device.&lt;/span&gt;&lt;strong&gt; &lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We’re on a mission to connect a billion people with optimism and civility, and looking for amazing talent to help us get there.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;A career at Roblox means you’ll be working to shape the future of human interaction, solving unique technical challenges at scale, and helping to create safer, more civil shared experiences for everyone.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;As a &lt;strong&gt;Backend Engineer&lt;/strong&gt; on the &lt;strong&gt;Co-Experience team&lt;/strong&gt;, you will work on high-visibility initiatives that define the future of age-appropriate communication. Using modern technologies, you will build and maintain a social ecosystem that ensures safe, civil, and meaningful interactions across diverse age groups.&lt;/p&gt;
&lt;p&gt;We are kind, highly collaborative, and draw on a mix of startup and large company backgrounds to iterate faster within Roblox.&lt;/p&gt;
&lt;p&gt;Our primary product is a &lt;strong&gt;platform-level Party System&lt;/strong&gt;. As the heartbeat of social interaction on Roblox, this system enables users to coordinate, form groups, and stay connected as they navigate across servers and immersive experiences.&lt;/p&gt;
&lt;p&gt;While we have a strong foundation of chat, voice, gameplay mechanics, and creator APIs, we need your expertise to strengthen our backend infrastructure, build out new features, and accelerate our path toward product-market fit. As we scale, your work will directly impact our global community and support the company’s top-line growth.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You Have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;An undergraduate/graduate degree in computer science, engineering or a related field.&lt;/li&gt;
&lt;li&gt;2+ years of experience in working on microservice architectures with a proven track record in addressing scalability and reliability challenges.&lt;/li&gt;
&lt;li&gt;1+ years of experience building systems behind consumer-facing APIs that can handle large numbers of concurrent users.&lt;/li&gt;
&lt;li&gt;Strong understanding of server-side development and design principles, with proficiency in at least one compiled language such as C#, C++, Java, Golang, or other.&lt;/li&gt;
&lt;li&gt;Strong product intuition - you think in terms of user experience, tradeoffs, and measurable outcomes, as well as system design.&lt;/li&gt;
&lt;li&gt;A track record of leveraging AI-assisted development tools to maximize engineering velocity, allowing you to rapidly prototype, iterate on complex logic, and move from ideation to production-ready code with high efficiency.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;You Will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Collaborate within a multi-functional team that includes product, design, UXR, frontend and backend engineering.&lt;/li&gt;
&lt;li&gt;Maintain, improve and scale the Roblox party system to support millions of concurrent users.&lt;/li&gt;
&lt;li&gt;Participate in design and develop service infrastructure empowering Roblox creators to unlock new ways to co-experience for their users.&lt;/li&gt;
&lt;li&gt;Partner with other engineering teams (infrastructure, matchmaking, chat, voice, trust and safety) to integrate multiple systems in a reusable, performant and safe manner.&lt;/li&gt;
&lt;li&gt;Self-organize and take ownership of projects throughout their full lifecycle.&lt;/li&gt;
&lt;li&gt;Maintain high quality standards while iterating on features with live production traffic.&lt;/li&gt;
&lt;li&gt;Mentor interns.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;You may redact age, date of birth, and dates of attendance/graduation from your resume if you prefer.&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;For roles that are based at our headquarters in San Mateo, CA: The starting base pay for this position is as shown below. The actual base pay is dependent upon a variety of job-related factors such as professional background, training, work experience, location, business needs and market demand. Therefore, in some circumstances, the actual salary could fall outside of this expected range. This pay range is subject to change and may be modified in the future. All full-time employees are also eligible for equity compensation and for benefits as described on &lt;strong&gt;&lt;a href=&quot;https://careers.roblox.com/total-rewards&quot;&gt;this page&lt;/a&gt;&lt;/strong&gt;.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Annual Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$153,120&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$196,750 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Roles that are based in an office are onsite Tuesday, Wednesday, and Thursday, with optional presence on Monday and Friday (unless otherwise noted).&lt;/p&gt;
&lt;p&gt;Roblox provides equal employment opportunities to all employees and applicants for employment and prohibits discrimination and harassment of any type without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other characteristic protected by federal, state or local laws. Roblox also provides reasonable accommodations to candidates with qualifying disabilities or religious beliefs during the recruiting process.&lt;/p&gt;
&lt;p&gt;For US based roles only, please note the Company may not be able to employ candidates for this role who have United States work authorization related to certain U.S. visa categories, or support future H-1B sponsorship at this time.&lt;/p&gt;&lt;/div&gt;

mbaexchange-sofi:greenhouse:7701314003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;a href=&quot;https://www.sofi.com/sofi-employee-applicant-privacy-notice/&quot; target=&quot;_blank&quot;&gt;&lt;strong&gt;Employee Applicant Privacy Notice&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Who we are:&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;
&lt;p&gt;Shape a brighter financial future with us.&lt;/p&gt;
&lt;p&gt;Together with our members, we’re changing the way people think about and interact with personal finance.&lt;/p&gt;
&lt;p&gt;We’re a next-generation financial services company and national bank using innovative, mobile-first technology to help our millions of members reach their goals. The industry is going through an unprecedented transformation, and we’re at the forefront. We’re proud to come to work every day knowing that what we do has a direct impact on people’s lives, with our core values guiding us every step of the way. &lt;strong&gt;Join us to invest in yourself, your career, and the financial world.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;The Role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Join us in revolutionizing the lending landscape. SoFi is seeking enthusiastic Staff Software Engineers who are ready to lead the design and implementation of key capabilities of the next generation of our financial services platform in support of our goals that put our members in control of their financial destiny.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Key qualifications of this role include:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Leading design and implementation efforts across multiple system domains to affect cross-team outcomes.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Resolving problems in the platform design and implementation where there are competing constraints and significant ambiguity.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Recognition as a subject matter expert across platform systems with the ability to contribute to the resolution of systemic issues.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ability to define the architectural direction and evolutionary strategy for critical subsystems within the platform.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ability to drive alignment across teams resolving technical and organizational conflicts.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Raises the engineering maturity of the organization by consistently upholding the org-wide quality, reliability, and security policies.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ability to align technology decisions with company strategy, accounting for risk and growth constraints.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Maintains standards of excellence through code and design reviews, mentors more junior engineers, and contributes to team efficiency, beyond personal output.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Is a key participant in recruiting processes.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Do&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As an established technical leader within our team, you will focus on designing and implementing the features, capabilities, and member experiences for our market-leading loan products. This role involves full product lifecycle engagement, from initial concept to production deployment. Your responsibilities include creating durable designs, strong individual contributions in implementing new capabilities, and leading by example to improve engineering excellence and efficiency across the team. Success in the role will require close technical collaboration with Product, Marketing, Operations, Business, Legal, and Compliance teams. You will be a key stakeholder in those partnerships, responsible for driving alignment and delivering technical solutions that provide outstanding value to our members.&lt;br&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Need&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Bachelor&#39;s or Master&#39;s degree in Computer Science, or Software Engineering&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;5+ years as a professional, full-time Software Engineer, or similar relevant work experience.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;2+ years in a technical leadership role.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Proficient coding in Java, Kotlin, or other similar object-oriented programming language.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience with public cloud compute, storage, and infrastructure.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience with Kafka, Docker, Kubernetes, and Spring Boot or similar frameworks.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Deep understanding of relational and document database fundamentals.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Deep understanding of fundamental distributed systems concepts.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Deep understanding of microservices design principles and architecture.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience with performance tuning and optimizing data access patterns.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Proficient working with GIT and related CI/CD systems.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Familiarity with Agile methodologies.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ability to produce clear and meaningful design and operational documentation artifacts.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Nice To Have&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Experience scaling highly-available, mission-critical systems.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience with AWS technologies – DynamoDB, RDS, Lambda, Kinesis, SQS, S3, and Athena.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
